extends "res://addons/godot_mcp/commands/base_command.gd"

## Runs the project in a separate headless Godot process and returns its output.
##
## This is the CI-shaped half of the toolset: projects whose test suites run as
## `godot --headless --path <project> res://tests/runner.tscn` were previously
## invisible to MCP, because every other tool talks to the live editor instead.
##
## The child process writes to a temp file via the platform shell rather than a
## pipe: a pipe's buffer fills up on verbose runs and deadlocks the child, and
## OS.execute() would block the whole editor until the run finished.

## Set in the child's environment so the MCP IPC autoloads disable themselves
## there. Referenced by mcp_screenshot_service.gd and its two siblings.
const HEADLESS_CHILD_ENV := "GODOT_MCP_HEADLESS_CHILD"

const _DEFAULT_TIMEOUT_SEC := 120.0
const _MAX_TIMEOUT_SEC := 900.0
const _POLL_INTERVAL_SEC := 0.25
## How long to wait for a killed process tree to actually disappear.
const _KILL_CONFIRM_SEC := 2.0
const _MAX_OUTPUT_CHARS := 100000
## Concurrent runs are possible — the router dispatches deferred commands and
## several MCP sessions can share one editor — so every run gets its own files.
var _run_counter := 0

class RunPaths:
	var log_path: String
	var exit_path: String
	var runner_path: String

	func _init(prefix: String, is_windows: bool) -> void:
		log_path = "%s.log" % prefix
		exit_path = "%s.exit" % prefix
		runner_path = "%s.bat" % prefix if is_windows else "%s.sh" % prefix

	func cleanup() -> void:
		for p: String in [log_path, exit_path, runner_path]:
			DirAccess.remove_absolute(ProjectSettings.globalize_path(p))


func get_commands() -> Dictionary:
	return {
		"run_headless_scene": _run_headless_scene,
		"run_headless_script": _run_headless_script,
		"get_godot_executable": _get_godot_executable,
	}


func _get_godot_executable(_params: Dictionary) -> Dictionary:
	return success({
		"executable": OS.get_executable_path(),
		"project_path": ProjectSettings.globalize_path("res://"),
		"platform": OS.get_name(),
	})


func _run_headless_scene(params: Dictionary) -> Dictionary:
	var result := require_string(params, "scene_path")
	if result[1] != null:
		return result[1]
	var scene_path: String = result[0]

	if not scene_path.begins_with("res://"):
		return error_invalid_params("scene_path must be a res:// path, got '%s'" % scene_path)
	if not FileAccess.file_exists(scene_path):
		return error_not_found("Scene '%s'" % scene_path)

	return await _run_headless(params, [scene_path], scene_path)


func _run_headless_script(params: Dictionary) -> Dictionary:
	var result := require_string(params, "script_path")
	if result[1] != null:
		return result[1]
	var script_path: String = result[0]

	if not script_path.begins_with("res://"):
		return error_invalid_params("script_path must be a res:// path, got '%s'" % script_path)
	if not FileAccess.file_exists(script_path):
		return error_not_found("Script '%s'" % script_path)

	return await _run_headless(params, ["--script", script_path], script_path)


func _run_headless(params: Dictionary, target_args: Array, target: String) -> Dictionary:
	var godot_bin := OS.get_executable_path()
	if godot_bin.is_empty():
		return error_internal("Could not determine the Godot executable path")

	var project_dir := ProjectSettings.globalize_path("res://")
	var timeout_sec: float = clampf(
		optional_float(params, "timeout_sec", _DEFAULT_TIMEOUT_SEC), 1.0, _MAX_TIMEOUT_SEC
	)

	var godot_args: Array = ["--headless", "--path", project_dir]
	godot_args.append_array(target_args)

	var quit_after: int = optional_int(params, "quit_after_frames", 0)
	if quit_after > 0:
		godot_args.append("--quit-after")
		godot_args.append(str(quit_after))

	var is_windows := OS.get_name() == "Windows"

	# Extra arguments for the project itself, after the `--` separator.
	var extra: Array = params.get("args", [])
	if extra is Array and not extra.is_empty():
		godot_args.append("--")
		for a: Variant in extra:
			var arg := str(a)
			if is_windows:
				# A batch file is line-oriented: a newline ends the command and
				# whatever follows runs as the next batch command. And there is
				# no escape for " inside a quoted batch string.
				if arg.contains('"'):
					return error_invalid_params(
						"Argument %s contains a double quote, which a Windows batch runner cannot represent." % arg
					)
				if arg.contains("\n") or arg.contains("\r"):
					return error_invalid_params(
						"Argument %s contains a line break, which would terminate the Windows batch command line." % arg
					)
			godot_args.append(arg)

	_run_counter += 1
	var prefix := "user://mcp_headless_%d_%d" % [OS.get_process_id(), _run_counter]
	var paths := RunPaths.new(prefix, is_windows)
	paths.cleanup()

	var shell := _shell_invocation(godot_bin, godot_args, paths, is_windows)
	if shell.is_empty():
		# It may have written the runner before failing on the path check.
		paths.cleanup()
		return error_internal("Could not prepare the headless runner script under user://")

	var pid := OS.create_process(shell[0], shell[1])
	if pid <= 0:
		paths.cleanup()
		return error_internal("Failed to start headless Godot process")

	# Measure against the clock rather than counting poll ticks: a stalled
	# editor frame makes a tick longer than _POLL_INTERVAL_SEC, and an
	# accumulator would then let the child run well past timeout_sec.
	var started_msec := Time.get_ticks_msec()
	var elapsed := 0.0
	var timed_out := false
	var kill_confirmed := true
	while OS.is_process_running(pid):
		await get_tree().create_timer(_POLL_INTERVAL_SEC).timeout
		elapsed = (Time.get_ticks_msec() - started_msec) / 1000.0
		if elapsed >= timeout_sec:
			# The child may have finished during the sleep above. Deciding from
			# the loop condition alone would report a successful run that
			# landed on the deadline as a timeout, and kill nothing.
			if not OS.is_process_running(pid):
				break
			timed_out = true
			_kill_process_tree(pid)
			kill_confirmed = await _await_process_exit(pid, _KILL_CONFIRM_SEC)
			break

	# A run that finished before the first poll never entered the loop, so take
	# the elapsed time here rather than leaving it at zero. On a timeout the
	# value is left as the deadline it hit, not the deadline plus the time
	# spent confirming the kill.
	if not timed_out:
		elapsed = (Time.get_ticks_msec() - started_msec) / 1000.0

	# Give the shell a moment to flush the redirect before reading it.
	await get_tree().create_timer(0.2).timeout

	var output := _read_text(paths.log_path)
	var truncated := false
	if output.length() > _MAX_OUTPUT_CHARS:
		output = output.substr(output.length() - _MAX_OUTPUT_CHARS)
		truncated = true

	var exit_code := -1
	var exit_text := _read_text(paths.exit_path).strip_edges()
	if exit_text.is_valid_int():
		exit_code = exit_text.to_int()

	paths.cleanup()

	var arg_strings := PackedStringArray()
	for a: Variant in godot_args:
		arg_strings.append(str(a))

	var payload := {
		"target": target,
		"command": "%s %s" % [godot_bin, " ".join(arg_strings)],
		"output": output,
		"exit_code": exit_code,
		"success": exit_code == 0 and not timed_out,
		"timed_out": timed_out,
		"duration_sec": snappedf(elapsed, 0.01),
	}
	if truncated:
		payload["output_truncated"] = true
		payload["note"] = "Output exceeded %d characters; only the tail is returned." % _MAX_OUTPUT_CHARS
	if timed_out:
		payload["kill_confirmed"] = kill_confirmed
		if kill_confirmed:
			payload["message"] = "Process exceeded timeout_sec=%s and was killed. Partial output is included." % str(timeout_sec)
		else:
			# Say so rather than claiming a kill that did not demonstrably happen.
			payload["message"] = "Process exceeded timeout_sec=%s and a kill was issued, but it was still running %ss later. It may survive this call — check for a stray Godot process. Partial output is included." % [
				str(timeout_sec), str(_KILL_CONFIRM_SEC)
			]

	return success(payload)


## Writes a runner script that redirects both streams to the log file and
## records the child's exit status in a second file, then returns the
## invocation for it.
##
## OS.create_process cannot capture output or an exit code on its own, and a
## pipe would deadlock a child that outprints the buffer before we read it.
## The command goes through a script file rather than an inline `-c` string
## because create_process re-quotes its arguments, which mangles a command line
## that already carries its own quoting — and paths with spaces are the norm on
## Windows and macOS.
func _shell_invocation(godot_bin: String, godot_args: Array, paths: RunPaths, is_windows: bool) -> Array:
	var native_log := _to_native(ProjectSettings.globalize_path(paths.log_path), is_windows)
	var native_exit := _to_native(ProjectSettings.globalize_path(paths.exit_path), is_windows)

	var command := _quote_arg(_to_native(godot_bin, is_windows), is_windows)
	for a: Variant in godot_args:
		command += " " + _quote_arg(str(a), is_windows)

	# The child runs the same editor binary and shares user://, so it would
	# otherwise pass the OS.has_feature("editor") check and start the MCP IPC
	# autoloads — which then race the editor's own play session for the
	# mcp_* request files. This marker tells the services to stand down.
	var body := ""
	if is_windows:
		# DisableDelayedExpansion matters when the machine has delayed expansion
		# on by default (a registry setting): a `!` in a path or argument would
		# otherwise be eaten or expanded.
		body = "@echo off\r\nsetlocal DisableDelayedExpansion\r\nset \"%s=1\"\r\n%s > %s 2>&1\r\necho %%errorlevel%% > %s\r\n" % [
			HEADLESS_CHILD_ENV, command, _quote_arg(native_log, true), _quote_arg(native_exit, true)
		]
	else:
		body = "#!/bin/sh\n%s=1\nexport %s\n%s > %s 2>&1\necho $? > %s\n" % [
			HEADLESS_CHILD_ENV, HEADLESS_CHILD_ENV,
			command, _quote_arg(native_log, false), _quote_arg(native_exit, false)
		]

	var file := FileAccess.open(paths.runner_path, FileAccess.WRITE)
	if file == null:
		return []
	file.store_string(body)
	file.close()

	var runner_native := _to_native(ProjectSettings.globalize_path(paths.runner_path), is_windows)
	if is_windows:
		# This path is parsed by cmd itself, where %VAR% is expanded regardless
		# of quoting and cannot be reliably escaped. Doubling only works inside
		# a batch file, not on cmd's own command line — so refuse rather than
		# run a command that means something else.
		if runner_native.contains("%"):
			push_error("[MCP] user:// path contains '%%', which cmd.exe would expand: %s" % runner_native)
			return []
		return ["cmd.exe", ["/c", runner_native]]
	return ["sh", [runner_native]]


## Quotes one argument for the generated runner script.
##
## Without this, a value containing $VAR, $(...), a backtick or a quote is
## expanded or executed by sh, and %VAR% is expanded by cmd — so ordinary
## caller-supplied arguments could be corrupted or run as shell syntax.
func _quote_arg(arg: String, is_windows: bool) -> String:
	if is_windows:
		# Batch neutralises % only by doubling it. A literal " cannot be
		# represented at all, which is why callers are rejected earlier.
		var escaped := arg.replace("%", "%%")
		# A run of backslashes immediately before the closing quote is read as
		# escapes by the callee's argv parser, so `C:\dir\` would swallow the
		# quote and merge with the next argument. Doubling them fixes it.
		var trailing := 0
		while trailing < escaped.length() and escaped[escaped.length() - 1 - trailing] == "\\":
			trailing += 1
		if trailing > 0:
			escaped += "\\".repeat(trailing)
		return '"%s"' % escaped
	# POSIX single quotes suppress every expansion; a literal ' is closed,
	# escaped and reopened.
	return "'%s'" % arg.replace("'", "'\\''")


## Waits for `pid` to disappear. Returns false if it is still running after
## `limit_sec`, so the caller can report an unconfirmed kill instead of
## asserting one that may not have happened.
func _await_process_exit(pid: int, limit_sec: float) -> bool:
	var waited := 0.0
	while OS.is_process_running(pid) and waited < limit_sec:
		await get_tree().create_timer(0.1).timeout
		waited += 0.1
	return not OS.is_process_running(pid)


## `pid` is the shell wrapper, not Godot itself. Killing only the shell orphans
## the Godot process, which then runs forever holding the log file open — so the
## whole tree has to go.
func _kill_process_tree(pid: int) -> void:
	var out: Array = []
	if OS.get_name() == "Windows":
		OS.execute("taskkill", ["/F", "/T", "/PID", str(pid)], out, true)
		return

	# pkill -P would only reach the shell's direct child. A test runner that
	# spawns its own helpers (a server, workers) would leave those running
	# after Godot exits, so walk the whole descendant tree depth-first.
	#
	# The script has to go through a FILE. Passing it inline to OS.execute does
	# not work: measured on Linux, every `$1`, `$c` and `$#` inside a `sh -c`
	# string arrives empty, so `pgrep -P ""` errors out and nothing is killed —
	# while the call still reports success. The pid is passed as an argv
	# element, which survives intact.
	var script_path := "user://mcp_kill_tree.sh"
	var file := FileAccess.open(script_path, FileAccess.WRITE)
	if file == null:
		push_error("[MCP] Could not write the kill helper; falling back to killing only the runner.")
		OS.kill(pid)
		return
	file.store_string(
		"#!/bin/sh\n"
		+ "kill_tree() {\n"
		+ "  for c in $(pgrep -P \"$1\" 2>/dev/null); do kill_tree \"$c\"; done\n"
		+ "  kill -9 \"$1\" 2>/dev/null\n"
		+ "}\n"
		+ "kill_tree \"$1\"\n"
	)
	file.close()

	OS.execute("sh", [ProjectSettings.globalize_path(script_path), str(pid)], out, true)
	OS.kill(pid)
	DirAccess.remove_absolute(ProjectSettings.globalize_path(script_path))


## Godot reports forward-slash paths everywhere; cmd.exe redirects want backslashes.
func _to_native(path: String, is_windows: bool) -> String:
	return path.replace("/", "\\") if is_windows else path


func _read_text(path: String) -> String:
	var file := FileAccess.open(path, FileAccess.READ)
	if file == null:
		return ""
	var text := file.get_as_text()
	file.close()
	return text@tool
extends "res://addons/godot_mcp/commands/base_command.gd"

const COMMANDS_PATH := "user://mcp_input_commands"


func get_commands() -> Dictionary:
	return {
		"simulate_key": _simulate_key,
		"simulate_mouse_click": _simulate_mouse_click,
		"simulate_mouse_move": _simulate_mouse_move,
		"simulate_action": _simulate_action,
		"simulate_sequence": _simulate_sequence,
	}


func _simulate_key(params: Dictionary) -> Dictionary:
	var result := require_string(params, "keycode")
	if result[1] != null:
		return result[1]
	var keycode: String = result[0]

	var pressed: bool = optional_bool(params, "pressed", true)
	var shift: bool = optional_bool(params, "shift", false)
	var ctrl: bool = optional_bool(params, "ctrl", false)
	var alt: bool = optional_bool(params, "alt", false)

	var event := {
		"type": "key",
		"keycode": keycode,
		"pressed": pressed,
		"shift": shift,
		"ctrl": ctrl,
		"alt": alt,
	}
	_write_commands([event])
	return success({"sent": true, "event": event})


func _simulate_mouse_click(params: Dictionary) -> Dictionary:
	var button: int = optional_int(params, "button", 1)  # MOUSE_BUTTON_LEFT
	var pressed: bool = optional_bool(params, "pressed", true)
	var double_click: bool = optional_bool(params, "double_click", false)
	var auto_release: bool = optional_bool(params, "auto_release", true)
	var x: float = optional_float(params, "x", 0.0)
	var y: float = optional_float(params, "y", 0.0)

	var press_event := {
		"type": "mouse_button",
		"button": button,
		"pressed": pressed,
		"double_click": double_click,
		"position": {"x": x, "y": y},
	}

	# Auto-release: send press + release in sequence so UI buttons actually fire
	if pressed and auto_release:
		var release_event := press_event.duplicate()
		release_event["pressed"] = false
		var sequence_data := {
			"sequence_events": [press_event, release_event],
			"frame_delay": 1,
		}
		var json := JSON.stringify(sequence_data)
		var file := FileAccess.open(COMMANDS_PATH, FileAccess.WRITE)
		if file == null:
			return error_internal("Failed to write commands: %s" % error_string(FileAccess.get_open_error()))
		file.store_string(json)
		file.close()
		return success({"sent": true, "event": press_event, "auto_release": true})

	_write_commands([press_event])
	return success({"sent": true, "event": press_event})


func _simulate_mouse_move(params: Dictionary) -> Dictionary:
	var x: float = optional_float(params, "x", 0.0)
	var y: float = optional_float(params, "y", 0.0)
	var rel_x: float = optional_float(params, "relative_x", 0.0)
	var rel_y: float = optional_float(params, "relative_y", 0.0)
	var button_mask: int = optional_int(params, "button_mask", 0)
	var unhandled_explicit: bool = params.has("unhandled")
	var unhandled: bool = optional_bool(params, "unhandled", false)

	var event := {
		"type": "mouse_motion",
		"position": {"x": x, "y": y},
		"relative": {"x": rel_x, "y": rel_y},
		"button_mask": button_mask,
	}
	# Auto-enable unhandled for drag motions (camera-pan use case) ONLY when
	# the caller did NOT explicitly pass an "unhandled" key. If they passed
	# one — true or false — honor it. This lets UI drag-and-drop tests opt
	# back into normal GUI dispatch by passing unhandled: false explicitly.
	if unhandled_explicit:
		event["unhandled"] = unhandled
	elif button_mask > 0:
		event["unhandled"] = true
	_write_commands([event])
	return success({"sent": true, "event": event})


func _simulate_action(params: Dictionary) -> Dictionary:
	var result := require_string(params, "action")
	if result[1] != null:
		return result[1]
	var action_name: String = result[0]

	var pressed: bool = optional_bool(params, "pressed", true)
	var strength: float = optional_float(params, "strength", 1.0)

	var event := {
		"type": "action",
		"action": action_name,
		"pressed": pressed,
		"strength": strength,
	}
	_write_commands([event])
	return success({"sent": true, "event": event})


func _simulate_sequence(params: Dictionary) -> Dictionary:
	if not params.has("events") or not params["events"] is Array:
		return error_invalid_params("Missing required parameter: events (Array)")

	var events: Array = params["events"]
	if events.is_empty():
		return error_invalid_params("Events array is empty")

	var frame_delay: int = optional_int(params, "frame_delay", 1)

	for entry: Variant in events:
		# Typed iteration would raise on a non-Dictionary entry, and `as String`
		# raises on a non-String type — both abort before any response is sent.
		if not entry is Dictionary:
			return error_invalid_params("Each sequence event must be an object, got %s" % type_string(typeof(entry)))
		var event_data: Dictionary = entry
		if not event_data.has("type") or not event_data["type"] is String or (event_data["type"] as String).is_empty():
			return error_invalid_params("Invalid event in sequence: %s" % str(event_data))

	if frame_delay <= 0:
		# All events in one frame - write as plain array
		_write_commands(events)
	else:
		# Sequence with frame delay - game side handles timing
		var sequence_data := {
			"sequence_events": events,
			"frame_delay": frame_delay,
		}
		var json := JSON.stringify(sequence_data)
		var file := FileAccess.open(COMMANDS_PATH, FileAccess.WRITE)
		if file == null:
			return error_internal("Failed to write commands: %s" % error_string(FileAccess.get_open_error()))
		file.store_string(json)
		file.close()

	return success({"sent": true, "event_count": events.size(), "frame_delay": frame_delay})


func _write_commands(events: Array) -> void:
	var json := JSON.stringify(events)
	var file := FileAccess.open(COMMANDS_PATH, FileAccess.WRITE)
	if file == null:
		push_error("[MCP Input] Failed to write commands: %s" % error_string(FileAccess.get_open_error()))
		return
	file.store_string(json)
	file.close()@tool
extends "res://addons/godot_mcp/commands/base_command.gd"


func get_commands() -> Dictionary:
	return {
		"get_input_actions": _get_input_actions,
		"set_input_action": _set_input_action,
	}


func _get_input_actions(params: Dictionary) -> Dictionary:
	var filter: String = optional_string(params, "filter", "")
	var include_builtin: bool = optional_bool(params, "include_builtin", false)

	var actions: Dictionary = {}
	for action: StringName in InputMap.get_actions():
		var action_str := str(action)
		if not include_builtin:
			# Skip built-in UI actions
			if action_str.begins_with("ui_"):
				continue
			# Skip editor-registered actions (spatial_editor/*, etc.) — the addon
			# runs in the editor process, so InputMap also carries the editor's
			# own actions, which are not part of the project's InputMap
			if not ProjectSettings.has_setting("input/" + action_str):
				continue
		# Apply filter
		if not filter.is_empty() and not action_str.contains(filter):
			continue

		var events: Array = []
		for event: InputEvent in InputMap.action_get_events(action):
			events.append(_serialize_event(event))

		actions[action_str] = {
			"deadzone": InputMap.action_get_deadzone(action),
			"events": events,
		}

	return success({"actions": actions, "count": actions.size()})


func _set_input_action(params: Dictionary) -> Dictionary:
	var result := require_string(params, "action")
	if result[1] != null:
		return result[1]
	var action_name: String = result[0]

	if not params.has("events") or not params["events"] is Array:
		return error_invalid_params("'events' array is required")
	var event_defs: Array = params["events"]

	var deadzone: float = optional_float(params, "deadzone", 0.5)

	# Build the events array
	var events: Array[InputEvent] = []
	for event_def in event_defs:
		if not event_def is Dictionary:
			continue
		var event := _parse_event(event_def)
		if event != null:
			events.append(event)

	# Save to ProjectSettings
	var setting_value := {
		"deadzone": deadzone,
		"events": events,
	}

	ProjectSettings.set_setting("input/" + action_name, setting_value)
	var err := ProjectSettings.save()
	if err != OK:
		return error_internal("Failed to save project settings: %s" % error_string(err))

	# Also update the runtime InputMap
	if not InputMap.has_action(action_name):
		InputMap.add_action(action_name, deadzone)
	else:
		InputMap.action_set_deadzone(action_name, deadzone)
		InputMap.action_erase_events(action_name)
	for event in events:
		InputMap.action_add_event(action_name, event)

	return success({
		"action": action_name,
		"deadzone": deadzone,
		"events_count": events.size(),
		"saved": true,
	})


func _serialize_event(event: InputEvent) -> Dictionary:
	if event is InputEventKey:
		var key_event: InputEventKey = event
		var info := {
			"type": "key",
			"keycode": OS.get_keycode_string(key_event.keycode) if key_event.keycode != KEY_NONE else "",
			"physical_keycode": OS.get_keycode_string(key_event.physical_keycode) if key_event.physical_keycode != KEY_NONE else "",
		}
		if key_event.ctrl_pressed: info["ctrl"] = true
		if key_event.shift_pressed: info["shift"] = true
		if key_event.alt_pressed: info["alt"] = true
		if key_event.meta_pressed: info["meta"] = true
		return info
	elif event is InputEventMouseButton:
		var mb_event: InputEventMouseButton = event
		return {
			"type": "mouse_button",
			"button_index": mb_event.button_index,
		}
	elif event is InputEventJoypadButton:
		var jb_event: InputEventJoypadButton = event
		return {
			"type": "joypad_button",
			"button_index": jb_event.button_index,
		}
	elif event is InputEventJoypadMotion:
		var jm_event: InputEventJoypadMotion = event
		return {
			"type": "joypad_motion",
			"axis": jm_event.axis,
			"axis_value": jm_event.axis_value,
		}
	return {"type": event.get_class()}


func _parse_event(def: Dictionary) -> InputEvent:
	var type: String = def.get("type", "")
	match type:
		"key":
			var event := InputEventKey.new()
			var keycode_str: String = def.get("keycode", "")
			if not keycode_str.is_empty():
				event.keycode = OS.find_keycode_from_string(keycode_str)
			var phys_str: String = def.get("physical_keycode", "")
			if not phys_str.is_empty():
				event.physical_keycode = OS.find_keycode_from_string(phys_str)
			event.ctrl_pressed = def.get("ctrl", false)
			event.shift_pressed = def.get("shift", false)
			event.alt_pressed = def.get("alt", false)
			event.meta_pressed = def.get("meta", false)
			return event
		"mouse_button":
			var event := InputEventMouseButton.new()
			event.button_index = int(def.get("button_index", 1))
			return event
		"joypad_button":
			var event := InputEventJoypadButton.new()
			event.button_index = int(def.get("button_index", 0))
			return event
		"joypad_motion":
			var event := InputEventJoypadMotion.new()
			event.axis = int(def.get("axis", 0))
			event.axis_value = float(def.get("axis_value", 1.0))
			return event
	return null@tool
extends "res://addons/godot_mcp/commands/base_command.gd"


func get_commands() -> Dictionary:
	return {
		"setup_navigation_region": _setup_navigation_region,
		"bake_navigation_mesh": _bake_navigation_mesh,
		"setup_navigation_agent": _setup_navigation_agent,
		"set_navigation_layers": _set_navigation_layers,
		"get_navigation_info": _get_navigation_info,
	}


func _is_3d_context(node: Node) -> bool:
	if node is Node3D:
		return true
	if node is Node2D:
		return false
	# Walk up to detect context
	var parent := node.get_parent()
	while parent != null:
		if parent is Node3D:
			return true
		if parent is Node2D:
			return false
		parent = parent.get_parent()
	return false


func _setup_navigation_region(params: Dictionary) -> Dictionary:
	var result := require_string(params, "node_path")
	if result[1] != null:
		return result[1]
	var node_path: String = result[0]

	var node := find_node_by_path(node_path)
	if node == null:
		return error_not_found("Node at '%s'" % node_path)
	var root := get_edited_root()
	if root == null:
		return error_no_scene()

	var force_mode: String = optional_string(params, "mode", "auto")
	var is_3d: bool
	match force_mode:
		"2d": is_3d = false
		"3d": is_3d = true
		_: is_3d = _is_3d_context(node)

	if is_3d:
		var region := NavigationRegion3D.new()
		region.name = optional_string(params, "name", "NavigationRegion3D")

		var nav_mesh := NavigationMesh.new()
		nav_mesh.agent_radius = optional_float(params, "agent_radius", 0.5)
		nav_mesh.agent_height = optional_float(params, "agent_height", 1.5)
		nav_mesh.agent_max_climb = optional_float(params, "agent_max_climb", 0.25)
		nav_mesh.agent_max_slope = optional_float(params, "agent_max_slope", 45.0)
		nav_mesh.cell_size = optional_float(params, "cell_size", 0.25)
		nav_mesh.cell_height = optional_float(params, "cell_height", 0.25)
		region.navigation_mesh = nav_mesh

		if params.has("navigation_layers"):
			region.navigation_layers = optional_int(params, "navigation_layers")

		add_child_with_undo(node, region, root, "MCP: Add NavigationRegion3D")

		return success({
			"node_path": str(region.get_path()),
			"type": "NavigationRegion3D",
			"agent_radius": nav_mesh.agent_radius,
			"agent_height": nav_mesh.agent_height,
			"cell_size": nav_mesh.cell_size,
			"created": true,
		})
	else:
		var region := NavigationRegion2D.new()
		region.name = optional_string(params, "name", "NavigationRegion2D")

		var nav_poly := NavigationPolygon.new()

		# Set parsed geometry source if available
		if params.has("source_geometry_mode"):
			var mode_str: String = str(params["source_geometry_mode"])
			match mode_str:
				"root_node": nav_poly.source_geometry_mode = NavigationPolygon.SOURCE_GEOMETRY_ROOT_NODE_CHILDREN
				"groups_with_children": nav_poly.source_geometry_mode = NavigationPolygon.SOURCE_GEOMETRY_GROUPS_WITH_CHILDREN
				"groups_explicit": nav_poly.source_geometry_mode = NavigationPolygon.SOURCE_GEOMETRY_GROUPS_EXPLICIT

		if params.has("cell_size"):
			nav_poly.cell_size = optional_float(params, "cell_size")

		if params.has("agent_radius"):
			nav_poly.agent_radius = optional_float(params, "agent_radius")

		region.navigation_polygon = nav_poly

		if params.has("navigation_layers"):
			region.navigation_layers = optional_int(params, "navigation_layers")

		add_child_with_undo(node, region, root, "MCP: Add NavigationRegion2D")

		return success({
			"node_path": str(region.get_path()),
			"type": "NavigationRegion2D",
			"cell_size": nav_poly.cell_size,
			"created": true,
		})


func _bake_navigation_mesh(params: Dictionary) -> Dictionary:
	var result := require_string(params, "node_path")
	if result[1] != null:
		return result[1]
	var node_path: String = result[0]

	var node := find_node_by_path(node_path)
	if node == null:
		return error_not_found("Node at '%s'" % node_path)
	var root := get_edited_root()
	if root == null:
		return error_no_scene()

	if node is NavigationRegion3D:
		var region: NavigationRegion3D = node as NavigationRegion3D
		if region.navigation_mesh == null:
			return error_invalid_params("NavigationRegion3D has no NavigationMesh resource")
		region.bake_navigation_mesh()
		mark_current_scene_unsaved()
		return success({
			"node_path": node_path,
			"type": "NavigationRegion3D",
			"baked": true,
		})

	elif node is NavigationRegion2D:
		var region: NavigationRegion2D = node as NavigationRegion2D
		if region.navigation_polygon == null:
			var nav_poly := NavigationPolygon.new()
			region.navigation_polygon = nav_poly

		# Set outline vertices from params
		if params.has("outline"):
			var outline_data: Array = params["outline"]
			var outline := PackedVector2Array()
			for point in outline_data:
				if point is Array and point.size() >= 2:
					outline.append(Vector2(float(point[0]), float(point[1])))
				elif point is Dictionary:
					outline.append(Vector2(float(point.get("x", 0)), float(point.get("y", 0))))

			if outline.size() >= 3:
				# Clear existing outlines
				while region.navigation_polygon.get_outline_count() > 0:
					region.navigation_polygon.remove_outline(0)
				region.navigation_polygon.add_outline(outline)
				region.navigation_polygon.make_polygons_from_outlines()
				mark_current_scene_unsaved()
				return success({
					"node_path": node_path,
					"type": "NavigationRegion2D",
					"outline_vertices": outline.size(),
					"baked": true,
				})
			else:
				return error_invalid_params("Outline must have at least 3 vertices")
		else:
			# Try baking from source geometry
			region.bake_navigation_polygon()
			mark_current_scene_unsaved()
			return success({
				"node_path": node_path,
				"type": "NavigationRegion2D",
				"baked": true,
			})

	return error_invalid_params("Node '%s' is not a NavigationRegion2D or NavigationRegion3D" % node_path)


func _setup_navigation_agent(params: Dictionary) -> Dictionary:
	var result := require_string(params, "node_path")
	if result[1] != null:
		return result[1]
	var node_path: String = result[0]

	var node := find_node_by_path(node_path)
	if node == null:
		return error_not_found("Node at '%s'" % node_path)
	var root := get_edited_root()
